+static util::Result<void> ReobfuscateBlocksIfRequested(NodeContext& node, const ArgsManager& args)
+{
+    const auto arg{args.GetArg("-reobfuscate-blocks", "0")};
+    auto requested_key{Obfuscation::KeyFromHex(arg)};
+    if (!requested_key && !arg.empty() && arg != "0" && arg != "1") {
+        return util::Error{strprintf(_("Invalid -reobfuscate-blocks value '%s'"), arg)};
+    }
+
+    const auto blocks_dir{args.GetBlocksDirPath()};
+    const bool pending{node::BlockReobfuscationPending(blocks_dir)};
+    if (arg == "0" && !pending) return {};
+
+    if (!args.GetBoolArg("-blocksxor", kernel::DEFAULT_XOR_BLOCKSDIR)) {
+        if (!requested_key && pending) requested_key = Obfuscation::Key{};
+        if (requested_key != Obfuscation::Key{}) { // only an explicit or resumed zero key is allowed
+            return util::Error{_("Block reobfuscation cannot proceed with -blocksxor=0")};
+        }
+    }
+    try {
+        uiInterface.InitMessage(_("Reobfuscating blocks…"));
+        node::ObfuscateBlocks(*Assert(node.shutdown_signal), *Assert(node.notifications), blocks_dir, requested_key);
+    } catch (const std::exception& e) {
+        return util::Error{strprintf(_("Block reobfuscation failed: %s"), e.what())};
+    }
+    return {};
